    0x000000000000800a, 0x800000008000000a, 0x8000000080008081,
    0x8000000000008080, 0x0000000080000001, 0x8000000080008008
]

r = [
    [0, 36, 3, 41, 18],
    [1, 44, 10, 45, 2],
    [62, 6, 43, 15, 61],
    [28, 55, 25, 21, 56],
    [27, 20, 39, 8, 14]
]

def keccak_f(A):
    for i in range(24):
        # Theta
        C = [A[x][0] ^ A[x][1] ^ A[x][2] ^ A[x][3] ^ A[x][4] for x in range(5)]
        D = [C[(x-1)%5] ^ ROL(C[(x+1)%5], 1) for x in range(5)]
        for x in range(5):
            for y in range(5):
                A[x][y] ^= D[x]
        # Rho and Pi
        B = [[0]*5 for _ in range(5)]
        for x in range(5):
            for y in range(5):
                B[y][(2*x+3*y)%5] = ROL(A[x][y], r[x][y])
        # Chi
        for x in range(5):
            for y in range(5):
                A[x][y] = B[x][y] ^ ((~B[(x+1)%5][y]) & B[(x+2)%5][y])
        # Iota
        A[0][0] ^= RC[i]
    return A

def keccak256(data: bytes) -> str:
    rate = 136
    data = bytearray(data)
    data.append(0x01)
    while len(data) % rate != 0:
        data.append(0x00)
    data[-1] |= 0x80

    A = [[0]*5 for _ in range(5)]
    for i in range(0, len(data), rate):
        block = data[i:i+rate]
        for x in range(5):
            for y in range(5):
                if (x + 5*y)*8 < rate:
                    idx = (x + 5*y)*8
                    val = int.from_bytes(block[idx:idx+8], 'little')
                    A[x][y] ^= val
        A = keccak_f(A)

    out = bytearray()
    for y in range(5):
        for x in range(5):
            if len(out) < 32:
                out.extend(A[x][y].to_bytes(8, 'little'))
    return out[:32].hex()

if __name__ == '__main__':
    print(keccak256(b"foo(uint256)"))
